using System.Text;
using MatCan.Core.Data;
using MatCan.Core.Documents;

namespace MatCan.Tests.Core;

public sealed class ValueFormatTests
{
    // The expected values come from the engine: EngineAgreementData.FormatCases is generated by a node script that calls DtEngine.formatValue({ type, decimals }, raw, locale)
    // (the same ICU as the browser). The two sides must never drift apart.
    [Fact]
    public void Format_gives_the_same_text_as_the_engine()
    {
        Assert.True(EngineAgreementData.FormatCases.Length >= 40);
        var failures = new List<string>();
        foreach (var (type, decimals, raw, locale, expected) in EngineAgreementData.FormatCases)
        {
            var actual = ValueFormat.Format(type, decimals, raw, locale);
            if (actual != expected)
            {
                failures.Add($"{type}/{decimals}/{locale} '{raw}': engine '{expected}', C# '{actual}'");
            }
        }

        Assert.True(failures.Count == 0, string.Join(Environment.NewLine, failures));
    }

    [Theory]
    [InlineData("2.99", 2.99)]
    [InlineData("2,99", 2.99)]
    [InlineData("1.234,56", 1234.56)]
    [InlineData("1,234.56", 1234.56)]
    [InlineData("1.234.567", 1234567)]
    [InlineData("1,234,567", 1234567)]
    [InlineData("2,99 €", 2.99)]
    [InlineData("-3", -3)]
    [InlineData("+4,5", 4.5)]
    [InlineData("1 234,5", 1234.5)]
    [InlineData("1'234.50", 1234.5)]
    [InlineData("1 234,5", 1234.5)]
    [InlineData("1 234,5", 1234.5)]
    [InlineData("50 %", 50)]
    public void Numbers_are_parsed_in_either_notation(string text, double expected) => Assert.Equal(expected, ValueFormat.ParseNumber(text)!.Value, 9);

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("abc")]
    [InlineData("12abc")]
    [InlineData("1e3")]
    [InlineData(",")]
    [InlineData("-")]
    [InlineData("١٢٣")]
    public void Text_that_is_not_a_number_is_not_parsed(string? text) => Assert.Null(ValueFormat.ParseNumber(text));

    [Fact]
    public void The_engine_reference_cases_stay_in_the_table()
    {
        // Spot checks of the rules named in the documentation, so that a regeneration that changes them is noticed.
        Assert.Equal("2,99", ValueFormat.Format("price", null, "2.99"));
        Assert.Equal("1.234,50", ValueFormat.Format("price", 2, "1234.5"));
        Assert.Equal("-3,00", ValueFormat.Format("price", 2, "-3"));
        Assert.Equal("0,00", ValueFormat.Format("price", 2, "0"));
        Assert.Equal("1,01", ValueFormat.Format("price", 2, "1.005"));
        Assert.Equal("2,68", ValueFormat.Format("price", 2, "2.675"));
        Assert.Equal("-0,00", ValueFormat.Format("price", 2, "-0.001"));
        Assert.Equal("1,234.50", ValueFormat.Format("price", 2, "1234.5", "en-US"));
        Assert.Equal("1 234,50", ValueFormat.Format("price", 2, "1234.5", "fr-FR"));
    }

    [Fact]
    public void Number_without_decimals_stays_as_typed_and_text_is_untouched()
    {
        Assert.Equal("12,5", ValueFormat.Format("number", null, " 12,5 "));
        Assert.Equal(" Käse ", ValueFormat.Format("text", null, " Käse "));
        Assert.Equal("a\nb", ValueFormat.Format("multiline", null, "a\nb"));
        Assert.Equal("flag-de", ValueFormat.Format("image", null, " flag-de "));
        Assert.Equal(string.Empty, ValueFormat.Format("price", 2, null));
        Assert.Equal(string.Empty, ValueFormat.Format("price", 2, "  "));
        Assert.Equal("abc", ValueFormat.Format("price", 2, "abc"));
    }

    [Fact]
    public void Decimals_are_limited_to_four()
    {
        Assert.Equal("1,5000", ValueFormat.Format("number", 9, "1.5"));
        Assert.Equal("2", ValueFormat.Format("number", -3, "1.5"));
    }

    [Fact]
    public void An_unknown_or_empty_locale_falls_back_to_german()
    {
        Assert.Equal("1.234,50", ValueFormat.Format("price", 2, "1234.5", ""));
        Assert.Equal("1.234,50", ValueFormat.Format("price", 2, "1234.5", "not a locale"));
    }

    [Fact]
    public void A_field_definition_can_be_used_directly()
    {
        var field = new FieldDef("Preis", "Preis", "price", "", null, null, false);
        Assert.Equal("2,50", ValueFormat.Format(field, "2.5", "de-DE"));
        Assert.True(ValueFormat.IsEmpty(" "));
        Assert.False(ValueFormat.IsEmpty("0"));
    }

    [Fact]
    public void Huge_values_do_not_overflow()
    {
        Assert.Equal("1.000.000.000.000.000.000.000,00", ValueFormat.Format("price", 2, "1" + new string('0', 21)));
    }
}

public sealed class CsvTests
{
    private static List<List<string>> Rows(string text, char? delimiter = null)
        => [.. Csv.Parse(text, delimiter).Rows.Select(r => r.ToList())];

    [Fact]
    public void A_simple_file_with_semicolons()
    {
        var result = Csv.Parse("Name;Preis\r\nGouda;2,99\r\nBrie;3,50\r\n");
        Assert.Equal(';', result.Delimiter);
        Assert.Equal(3, result.Rows.Count);
        Assert.Equal(["Brie", "3,50"], result.Rows[2]);
    }

    [Theory]
    [InlineData("a;b;c\n1;2;3\n", ';')]
    [InlineData("a,b,c\n1,2,3\n", ',')]
    [InlineData("a\tb\tc\n1\t2\t3\n", '\t')]
    [InlineData("a|b|c\n1|2|3\n", '|')]
    [InlineData("Name;Preis\nGouda;2,99\nBrie;3,5\n", ';')]
    [InlineData("a,b\n\"x;y;z\",\"1;2\"\n", ',')]
    [InlineData("single", ';')]
    [InlineData("", ';')]
    public void The_delimiter_is_detected(string text, char expected) => Assert.Equal(expected, Csv.DetectDelimiter(text));

    [Fact]
    public void Commas_inside_german_prices_do_not_fool_the_detection()
    {
        Assert.Equal(';', Csv.DetectDelimiter("Name;Preis;Menge\nGouda;2,99;5\nBrie;3,50;2\nFeta;1,25;7\n"));
    }

    [Fact]
    public void A_bom_is_removed()
    {
        var rows = Rows("﻿Name;Preis\nGouda;2");
        Assert.Equal("Name", rows[0][0]);
    }

    [Fact]
    public void Quotes_protect_delimiters_and_line_breaks()
    {
        var rows = Rows("Name;Text\n\"Gouda; jung\";\"zwei\nZeilen\"\n");
        Assert.Equal(2, rows.Count);
        Assert.Equal(["Gouda; jung", "zwei\nZeilen"], rows[1]);
    }

    [Fact]
    public void Doubled_quotes_are_one_quote()
    {
        Assert.Equal([["Er sagte \"Hallo\"", "x"]], Rows("\"Er sagte \"\"Hallo\"\"\";x"));
        Assert.Equal([["\"", ""]], Rows("\"\"\"\";\"\""));
    }

    [Fact]
    public void Empty_lines_and_lines_of_empty_cells_are_skipped()
    {
        var rows = Rows("a;b\n\n;\n  \n\r\n1;2\n\n");
        Assert.Equal(3, rows.Count);
        Assert.Equal(["  "], rows[1]);
        Assert.Equal(["1", "2"], rows[2]);
    }

    [Fact]
    public void Rows_keep_their_own_length()
    {
        var rows = Rows("a;b;c\n1;2\n3;4;5;6\n");
        Assert.Equal([3, 2, 4], rows.Select(r => r.Count));
    }

    [Fact]
    public void All_line_ends_are_understood()
    {
        Assert.Equal(3, Rows("a\nb\nc").Count);
        Assert.Equal(3, Rows("a\r\nb\r\nc").Count);
        Assert.Equal(3, Rows("a\rb\rc").Count);
    }

    [Fact]
    public void An_unterminated_quote_takes_the_rest()
    {
        var rows = Rows("a;\"b\nc;d");
        Assert.Equal(["a", "b\nc;d"], Assert.Single(rows));
    }

    [Fact]
    public void An_empty_quoted_cell_at_the_end_is_kept()
    {
        Assert.Equal(["a", ""], Assert.Single(Rows("a;\"\"")));
        Assert.Equal(["a", ""], Assert.Single(Rows("a;")));
    }

    [Fact]
    public void A_given_delimiter_wins_over_detection()
    {
        var result = Csv.Parse("a;b,c", ',');
        Assert.Equal(',', result.Delimiter);
        Assert.Equal(["a;b", "c"], result.Rows[0]);
    }

    [Fact]
    public void Parsing_never_throws_on_odd_input()
    {
        foreach (var text in new[] { "\"", "\"\"\"", ";;;;", "\n\n\n", "\"a\"b\"c\"", "a\0b", new string('"', 1001) })
        {
            Csv.Parse(text);
        }
    }

    [Fact]
    public void Write_quotes_only_where_needed_and_ends_lines_with_crlf()
    {
        var text = Csv.Write([["Name", "Notiz"], ["Gouda; jung", "sagt \"hi\""], ["a\nb", " x"], ["plain", ""]]);
        Assert.Equal("Name;Notiz\r\n\"Gouda; jung\";\"sagt \"\"hi\"\"\"\r\n\"a\nb\";\" x\"\r\nplain;\r\n", text);
    }

    [Fact]
    public void Write_then_parse_gives_the_same_rows()
    {
        var original = new List<IReadOnlyList<string>>
        {
            new[] { "Name", "Beschreibung", "Preis" },
            new[] { "Käse \"Alt\"", "mild; würzig\nund kräftig", "2,99" },
            new[] { "Ärger", " vorn", "hinten " },
            new[] { "€uro", "ß", "日本語" },
            new[] { "", "x", "" },
        };
        foreach (var delimiter in new[] { ';', ',', '\t' })
        {
            var parsed = Csv.Parse(Csv.Write(original, delimiter), delimiter);
            Assert.Equal(original.Select(r => r.ToList()), parsed.Rows.Select(r => r.ToList()));
        }
    }

    [Fact]
    public void WriteBytes_starts_with_the_utf8_bom_and_reads_back()
    {
        var bytes = Csv.WriteBytes([["Käse", "ü"]]);
        Assert.Equal([0xEF, 0xBB, 0xBF], bytes.Take(3));
        Assert.Equal("Käse;ü\r\n", Encoding.UTF8.GetString(bytes, 3, bytes.Length - 3));
        Assert.Equal("Käse", Csv.Parse(Encoding.UTF8.GetString(bytes)).Rows[0][0]);
    }

    [Fact]
    public void Cells_that_look_like_formulas_are_written_as_they_are()
    {
        Assert.Equal("=1+1;-5;@x\r\n", Csv.Write([["=1+1", "-5", "@x"]]));
    }
}
